ALTER TABLE jobs ADD COLUMN IF NOT EXISTS salary_min NUMERIC(12,2), ADD COLUMN IF NOT EXISTS salary_max NUMERIC(12,2), ADD COLUMN IF NOT EXISTS salary_currency TEXT, ADD COLUMN IF NOT EXISTS is_remote BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS source_url TEXT;
ALTER TABLE applications ADD COLUMN IF NOT EXISTS metadata JSONB NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE IF NOT EXISTS otp_challenges(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,channel TEXT NOT NULL CHECK(channel IN ('email','sms')),target TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN ('verify_email','verify_phone','login')),code_hash TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ,attempts INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS otp_challenges_target_created_idx ON otp_challenges(target,created_at DESC);
CREATE TABLE IF NOT EXISTS resume_documents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,storage_key TEXT NOT NULL UNIQUE,filename TEXT NOT NULL,content_type TEXT NOT NULL,byte_size BIGINT NOT NULL,extracted_text TEXT NOT NULL,extracted_at TIMESTAMPTZ NOT NULL DEFAULT now(),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS resume_documents_user_created_idx ON resume_documents(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS provider_connections(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,provider TEXT NOT NULL,provider_account_id TEXT,account_email TEXT,access_token_encrypted TEXT,refresh_token_encrypted TEXT,token_expires_at TIMESTAMPTZ,scopes TEXT[] NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'connected',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,provider,provider_account_id));
CREATE INDEX IF NOT EXISTS provider_connections_user_idx ON provider_connections(user_id,provider);
CREATE TABLE IF NOT EXISTS oauth_states(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,provider TEXT NOT NULL,state_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS external_action_jobs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),approval_id UUID NOT NULL UNIQUE REFERENCES action_approvals(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','done','blocked','failed')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,provider_message_id TEXT,available_at TIMESTAMPTZ NOT NULL DEFAULT now(),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS external_action_jobs_ready_idx ON external_action_jobs(status,available_at,created_at);
CREATE TABLE IF NOT EXISTS user_memories(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,memory_key TEXT NOT NULL,memory_value TEXT NOT NULL,source TEXT NOT NULL DEFAULT 'user',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,memory_key));
CREATE INDEX IF NOT EXISTS user_memories_user_idx ON user_memories(user_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS job_source_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),source TEXT NOT NULL,board_key TEXT NOT NULL,fetched_count INTEGER NOT NULL DEFAULT 0,inserted_count INTEGER NOT NULL DEFAULT 0,updated_count INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL,error_message TEXT,started_at TIMESTAMPTZ NOT NULL DEFAULT now(),finished_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS channel_link_tokens(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,provider TEXT NOT NULL CHECK(provider IN ('whatsapp')),token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS channel_link_tokens_user_idx ON channel_link_tokens(user_id,created_at DESC);
